#include <cstddef>
#include <iostream>
#include <numeric>
#include <utility>
#include <vector>
struct Query {int type,base,a,b;};
int main(){
 std::ios::sync_with_stdio(false);std::cin.tie(nullptr);
 int n,q;if(!(std::cin>>n>>q))return 0;
 std::vector<Query> qs(q+1);std::vector<std::vector<int>> children(q+1),asks(q+1);
 for(int i=1;i<=q;++i){auto& x=qs[i];std::cin>>x.type>>x.base>>x.a>>x.b;++x.base;if(x.type==0)children[x.base].push_back(i);else asks[x.base].push_back(i);}
 std::vector<int> p(n,-1),answer(q+1,-1);auto leader=[&](int x){while(p[x]>=0)x=p[x];return x;};
 std::vector<std::pair<int,int>> history;
 struct Frame{int v;std::size_t next,mark;};std::vector<Frame> stack{{0,0,0}};
 auto enter=[&](int v){auto a=leader(qs[v].a),b=leader(qs[v].b);if(a!=b){if(p[a]>p[b])std::swap(a,b);history.emplace_back(a,p[a]);history.emplace_back(b,p[b]);p[a]+=p[b];p[b]=a;}};
 auto ask=[&](int v){for(auto i:asks[v])answer[i]=leader(qs[i].a)==leader(qs[i].b);};ask(0);
 while(!stack.empty()){
  auto& f=stack.back();
  if(f.next<children[f.v].size()){const auto v=children[f.v][f.next++];const auto mark=history.size();enter(v);ask(v);stack.push_back({v,0,mark});}
  else{auto mark=f.mark;while(history.size()>mark){auto [i,old]=history.back();history.pop_back();p[i]=old;}stack.pop_back();}
 }
 for(int i=1;i<=q;++i)if(qs[i].type==1)std::cout<<answer[i]<<'\n';
}

